public class SizePickerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String textOf(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        return "(missing)";
    }

    public static void main(String[] args) {
        try {
            SizePicker panel = new SizePicker();
            java.awt.Component priceC = find(panel, "price");
            java.awt.Component sizesC = find(panel, "sizes");
            check("price label correct right after construction", "$2.50", textOf(priceC));
            if (sizesC instanceof javax.swing.JComboBox) {
                javax.swing.JComboBox<?> combo = (javax.swing.JComboBox<?>) sizesC;
                check("combo has three entries", 3, combo.getItemCount());
                check("second entry", "medium", String.valueOf(combo.getItemAt(1)));
                combo.setSelectedIndex(1);
                check("medium price", "$3.75", textOf(priceC));
                combo.setSelectedIndex(2);
                check("large price", "$5.00", textOf(priceC));
                combo.setSelectedIndex(0);
                check("back to small", "$2.50", textOf(priceC));
            } else {
                failures++;
                System.out.println("FAIL  combo box not found by name");
            }
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

