import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;

public class SizePicker extends JPanel {

    private static final String[] SIZES = {"small", "medium", "large"};
    private static final double[] PRICES = {2.50, 3.75, 5.00};

    private final JComboBox<String> sizes = new JComboBox<>(SIZES);
    private final JLabel price = new JLabel("");

    public SizePicker() {
        sizes.setName("sizes");
        price.setName("price");
        add(sizes);
        add(price);
        sizes.addActionListener(e -> updatePrice());
        updatePrice();
    }

    private void updatePrice() {
        int index = sizes.getSelectedIndex();
        price.setText(String.format(java.util.Locale.US, "$%.2f", PRICES[index]));
    }
}
